<?php
require_once __DIR__ . '/config/bootstrap.php';
require_once __DIR__ . '/config/auth.php';
require_staff();

if(!isset($_SESSION['user_id'])&&!isset($_SESSION['usuario_id'])){header('Location:login.php');exit;}
require_once 'config/database.php';$db=getDBConnection();
$start=$_GET['start_date']??date('Y-m-01');$end=$_GET['end_date']??date('Y-m-d');$day=$_GET['fecha_dia']??date('Y-m-d');$period=$_GET['periodo']??'month';
function vd($d){$x=DateTime::createFromFormat('Y-m-d',$d);return $x&&$x->format('Y-m-d')===$d;}if($period==='day')$start=$end=$day;if(!vd($start)||!vd($end)||$start>$end){$start=date('Y-m-01');$end=date('Y-m-d');}
$q=$db->prepare("SELECT COUNT(*) cant,COALESCE(SUM(total),0) total,COALESCE(AVG(total),0) promedio FROM facturas WHERE estado='paid' AND fecha_emision BETWEEN ? AND ?");$q->execute([$start.' 00:00:00',$end.' 23:59:59']);$ventas=$q->fetch(PDO::FETCH_ASSOC);
$q=$db->prepare("SELECT COUNT(*) cant,COALESCE(SUM(monto),0) total FROM egresos WHERE estado='pagado' AND fecha BETWEEN ? AND ?");$q->execute([$start,$end]);$gastos=$q->fetch(PDO::FETCH_ASSOC);$resultado=(float)$ventas['total']-(float)$gastos['total'];
$q=$db->prepare("SELECT metodo_pago,COUNT(*) cant,COALESCE(SUM(total),0) total FROM facturas WHERE estado='paid' AND fecha_emision BETWEEN ? AND ? GROUP BY metodo_pago ORDER BY total DESC");$q->execute([$start.' 00:00:00',$end.' 23:59:59']);$metodos=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare("SELECT categoria,COUNT(*) cant,COALESCE(SUM(monto),0) total FROM egresos WHERE estado='pagado' AND fecha BETWEEN ? AND ? GROUP BY categoria ORDER BY total DESC");$q->execute([$start,$end]);$cats=$q->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="es"><head>
<?php if(function_exists('av_head')) av_head(); ?><meta charset="utf-8"><title>Reporte financiero</title><style>body{font-family:Arial;color:#222;margin:36px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #0f6c33;padding-bottom:12px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:25px 0}.card{border:1px solid #ddd;border-radius:10px;padding:18px}.n{font-size:26px;font-weight:bold;color:#0f6c33}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{border-bottom:1px solid #ddd;padding:10px;text-align:left}th{background:#f2f6f3}.actions{margin-bottom:20px}.btn{display:inline-block;padding:9px 13px;background:#0f6c33;color:#fff;text-decoration:none;border-radius:7px;border:0}@media print{.actions{display:none}body{margin:15mm}}@media(max-width:700px){.cards{grid-template-columns:1fr}}</style>    <link rel="stylesheet" href="css/app-optimized.css?v=20260812c">
</head><body><div class="actions"><button class="btn" onclick="print()">Imprimir / Guardar PDF</button> <a class="btn" href="dashboardfi.php">Volver</a></div><div class="head"><div><h1>Reporte financiero</h1><div><?=htmlspecialchars($start)?> al <?=htmlspecialchars($end)?></div></div><div>Generado <?=date('d/m/Y H:i')?></div></div><div class="cards"><div class="card"><div>Facturas cobradas</div><div class="n">$<?=number_format((float)$ventas['total'],2)?></div><small><?=number_format((int)$ventas['cant'])?> operaciones</small></div><div class="card"><div>Egresos pagados</div><div class="n">$<?=number_format((float)$gastos['total'],2)?></div><small><?=number_format((int)$gastos['cant'])?> registros</small></div><div class="card"><div>Resultado</div><div class="n">$<?=number_format($resultado,2)?></div><small>Ingresos por facturas menos egresos</small></div></div><h2>Cobros por método</h2><table><tr><th>Método</th><th>Operaciones</th><th>Total</th></tr><?php foreach($metodos as $r):?><tr><td><?=htmlspecialchars($r['metodo_pago']?:'Sin definir')?></td><td><?=$r['cant']?></td><td>$<?=number_format((float)$r['total'],2)?></td></tr><?php endforeach;?></table><h2>Egresos por categoría</h2><table><tr><th>Categoría</th><th>Registros</th><th>Total</th></tr><?php foreach($cats as $r):?><tr><td><?=htmlspecialchars($r['categoria'])?></td><td><?=$r['cant']?></td><td>$<?=number_format((float)$r['total'],2)?></td></tr><?php endforeach;?></table></body></html>
